# z56 CENTRAL: best unconditional slice range theta(k,l) = (1-3k)/(4(l-k)) over exponent pairs
# generated by A/B processes from (0,1) and from Bourgain's (13/84, 55/84) (epsilons dropped).
from fractions import Fraction as F
def A(p): k,l=p; return (k/(2*k+2),(k+l+1)/(2*k+2))
def B(p): k,l=p; return (l-F(1,2),k+F(1,2))
def theta(p):
    k,l=p
    return (1-3*k)/(4*(l-k)) if l>k else None
best=[]
seen=set()
frontier=[((F(0),F(1)),"(0,1)"),((F(13,84),F(55,84)),"Bourgain")]
for depth in range(9):
    new=[]
    for p,w in frontier:
        if p in seen: continue
        seen.add(p)
        t=theta(p)
        if t is not None: best.append((float(t),w,p))
        new.append((A(p),"A"+w)); 
        if not w.startswith("B"): new.append((B(p),"B"+w))
    frontier=new
best.sort(reverse=True)
for t,w,p in best[:12]: print(f"{t:.5f}  {w:30s} ({p[0]}, {p[1]})")
print("EPC limit (0,1/2):", 0.5)
